/*
 * A191490  Triangle generated by the recurrence T(n+1,k+1) = T(n,k+1) + n *
 *          T(n,k) + delta(n,k) with the initial values T(n,0) = 1 and T(0,k)
 *          = delta(k,0), where delta(n,k) is the Kronecker delta.
 * https://oeis.org/A191490
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the (row-major) flattening of the triangle T given by:
 *            T(0,0)=1, T(n,0)=1; for n≥1: T(n,k)=T(n‑1,k)+(n‑1)*T(n‑1,k‑1)
 *            for 1≤k≤n‑1 T(n,n)=(n‑1)*T(n‑1,n‑1)+1 For an index n, let r be
 *            the unique integer with r(r+1)/2 ≤ n < (r+1)(r+2)/2. Then
 *            a(n)=T(r, n‑r(r+1)/2)
 * Range:     u8 n <= 23, u16 n <= 49, u32 n <= 101, u64 n <= 247,
 *            u128 n <= 560, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

seq_t a(idx_t n)
{
    /* static cache of rows already computed */
    static seq_t **tri = NULL;      /* pointer to array of row pointers   */
    static idx_t rows = 0;          /* index of the last row built       */
    static idx_t cum  = 0;          /* total number of elements up to 'rows' */

    /* Initialise the first row on first call */
    if (!tri) {
        tri = (seq_t**)malloc(sizeof(seq_t*));
        tri[0] = (seq_t*)malloc(sizeof(seq_t));   /* row 0 has length 1   */
        tri[0][0] = (seq_t)1;
        rows = 0;
        cum  = 1;                       /* one element (row 0)   */
    }

    /* Extend the triangle until it contains at least n+1 elements */
    while (cum <= n) {
        idx_t r = rows + 1;                     /* new row index           */
        /* Reallocate array of row pointers */
        tri = (seq_t**)realloc(tri,
                                sizeof(seq_t*) * (r + 1));
        /* Allocate new row of length r+1 */
        tri[r] = (seq_t*)malloc(sizeof(seq_t) * (r + 1));
        tri[r][0] = (seq_t)1;                   /* first element of row r */

        seq_t *prev = tri[rows]; /* pointer to previous row */

        /* Compute interior elements (k = 1 … r‑1) */
        for (idx_t k = 1; k < r; ++k) {
            seq_t a_prev_k   = (k <= rows) ? prev[k]   : (seq_t)0;
            seq_t a_prev_k_1 = prev[k-1];
            tri[r][k] = a_prev_k + (seq_t)rows * a_prev_k_1;
        }

        /* Last element of the row (k = r) */
        tri[r][r] = (seq_t)rows * prev[rows] + (seq_t)1;

        /* Update state */
        rows = r;
        cum += r + 1;           /* number of elements in the new row */
    }

    /* Find row r that contains index n */
    idx_t r   = rows;
    idx_t base = (idx_t)((seq_t)r * ((seq_t)r + 1) / 2);
    idx_t k    = n - base;          /* column inside row r          */

    return tri[r][k];
}
